import { MakeLogicType, actions, afterMount, kea, listeners, path, reducers } from 'kea'
import { loaders } from 'kea-loaders'

import { lemonToast } from '@posthog/lemon-ui'

import { teamLogic } from 'scenes/teamLogic'

import { errorTrackingBuiltInFiltersList, errorTrackingBuiltInFiltersPartialUpdate } from '../../../generated/api'
import type { ErrorTrackingBuiltInFilterApi } from '../../../generated/api.schemas'

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface builtInFiltersLogicValues {
    builtInFilters: ErrorTrackingBuiltInFilterApi[] | null
    builtInFiltersLoadFailed: boolean
    builtInFiltersLoading: boolean
    pendingKeys: string[]
}

// Generated by kea-typegen. Update if you're an agent, ignore if you're human.
export interface builtInFiltersLogicActions {
    loadBuiltInFilters: () => any
    loadBuiltInFiltersFailure: (
        error: string,
        errorObject?: any
    ) => {
        error: string
        errorObject?: any
    }
    loadBuiltInFiltersSuccess: (
        builtInFilters: ErrorTrackingBuiltInFilterApi[],
        payload?: any
    ) => {
        builtInFilters: ErrorTrackingBuiltInFilterApi[]
        payload?: any
    }
    setFilterEnabled: (
        key: string,
        enabled: boolean
    ) => {
        enabled: boolean
        key: string
    }
    setFilterSaveFailed: (key: string) => {
        key: string
    }
    setFilterSaved: (filter: ErrorTrackingBuiltInFilterApi) => {
        filter: ErrorTrackingBuiltInFilterApi
    }
}

export type builtInFiltersLogicType = MakeLogicType<builtInFiltersLogicValues, builtInFiltersLogicActions>

export const builtInFiltersLogic = kea<builtInFiltersLogicType>([
    path([
        'products',
        'error_tracking',
        'scenes',
        'ErrorTrackingConfigurationScene',
        'built_in_filters',
        'builtInFiltersLogic',
    ]),

    actions({
        setFilterEnabled: (key: string, enabled: boolean) => ({ key, enabled }),
        setFilterSaved: (filter: ErrorTrackingBuiltInFilterApi) => ({ filter }),
        setFilterSaveFailed: (key: string) => ({ key }),
    }),

    loaders({
        builtInFilters: [
            null as ErrorTrackingBuiltInFilterApi[] | null,
            {
                loadBuiltInFilters: async () =>
                    await errorTrackingBuiltInFiltersList(String(teamLogic.values.currentTeamId)),
            },
        ],
    }),

    reducers({
        builtInFilters: {
            setFilterSaved: (state, { filter }) => state?.map((f) => (f.key === filter.key ? filter : f)) ?? state,
        },
        builtInFiltersLoadFailed: [
            false,
            {
                loadBuiltInFilters: () => false,
                loadBuiltInFiltersFailure: () => true,
            },
        ],
        // Keys with a request in flight, so each switch blocks a second toggle until its own request settles.
        pendingKeys: [
            [] as string[],
            {
                setFilterEnabled: (state, { key }) => [...state, key],
                setFilterSaved: (state, { filter }) => state.filter((k) => k !== filter.key),
                setFilterSaveFailed: (state, { key }) => state.filter((k) => k !== key),
            },
        ],
    }),

    listeners(({ actions }) => ({
        setFilterEnabled: async ({ key, enabled }) => {
            try {
                const filter = await errorTrackingBuiltInFiltersPartialUpdate(
                    String(teamLogic.values.currentTeamId),
                    key,
                    { enabled }
                )
                actions.setFilterSaved(filter)
            } catch {
                actions.setFilterSaveFailed(key)
                lemonToast.error("Couldn't update the rule. Try again, and if it keeps failing, contact support.")
            }
        },
    })),

    afterMount(({ actions }) => {
        actions.loadBuiltInFilters()
    }),
])
